{
     "title": "CSCI-589: Undergraduate Thesis Proposal and Preparation",
     "learningObjectives": [
       "Students will articulate the core components of a thesis proposal, including problem definition, methodology, and evaluation criteria.",
       "Students will demonstrate how to integrate ACM ethical guidelines and responsible research communication standards into their proposal development.",
       "Students will produce a structured proposal outline that aligns with supervisor requirements and academic integrity standards."
     ],
     "beats": [
       {
         "title": "Introduction to Thesis Preparation",
         "claim": "Students work with a supervising faculty member to complete their undergraduate thesis proposal, and do additional background preparation for the subject area and specific problem.",
         "example": "A student collaborates with their advisor to draft a proposal that outlines a machine learning project on educational data analysis.",
         "visualDirection": "Display a simple flowchart showing the sequence: Advisor Consultation -> Background Preparation -> Proposal Drafting -> Advisor Review.",
         "sourceIds": ["rit-csci-589"]
       },
       {
         "title": "Defining the Research Problem",
         "claim": "A research project narrows a question, reviews literature, and defines a reproducible method to address specific problems.",
         "example": "Students transform a broad interest in 'AI ethics' into a focused question about 'bias detection in automated grading tools.'",
         "visualDirection": "Show a Venn diagram comparing broad interests, literature gaps, and a clearly defined research question.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Methodology and Reproducibility",
         "claim": "Methods should be described well enough for readers to evaluate the work and ensure reproducibility.",
         "example": "Students document exact software versions, dataset sources, and step-by-step procedures for their thesis experiment.",
         "visualDirection": "Illustrate a checklist template with fields for 'Dataset Source', 'Code Repository', 'Parameter Settings', and 'Reproduction Steps'.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Ethical Computing Standards",
         "claim": "Computing professionals should be honest and trustworthy, avoid harm, and respect privacy and confidentiality.",
         "example": "Students include a section in their proposal detailing how they will anonymize student data and obtain necessary permissions.",
         "visualDirection": "Present a side-by-side comparison of 'Ethical Compliance' vs. 'Potential Harm' with checkmarks for privacy, fairness, and transparency.",
         "sourceIds": ["acm-code-of-ethics"]
       },
       {
         "title": "Responsible Technical Communication",
         "claim": "Responsible technical communication distinguishes claims from evidence and cites prior work to identify contributions.",
         "example": "Students structure their proposal to clearly separate their novel hypothesis from established literature findings.",
         "visualDirection": "Show a two-column layout: 'Claim' (student's contribution) vs. 'Evidence' (prior research citations), with arrows linking them.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Results and Limitations",
         "claim": "Results should be reported accurately rather than selected to create a misleading conclusion, and limitations should be made visible.",
         "example": "Students draft a subsection explicitly stating potential biases in their dataset and how they will validate their findings.",
         "visualDirection": "Create a template box labeled 'Limitations & Threats to Validity' with prompts for data constraints, methodological gaps, and mitigation strategies.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Research Integrity and Plagiarism",
         "claim": "Authors should preserve research integrity and avoid plagiarism, fabrication, and falsification.",
         "example": "Students use citation management tools to track all references and verify that all code and data are properly attributed.",
         "visualDirection": "Display a flowchart: 'Source Identification' -> 'Citation Formatting' -> 'Plagiarism Check' -> 'Integrity Verification'.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Supervisor Deliverables and Planning",
         "claim": "Additional deliverables set by the advisor are also required, such as source code, bibliographies, notes, and presentations.",
         "example": "Students create a project management tracker that logs weekly milestones for coding, literature review, and draft presentations.",
         "visualDirection": "Show a Gantt chart template with phases: 'Proposal Draft', 'Code Setup', 'Literature Review', 'Advisor Feedback', 'Final Submission'.",
         "sourceIds": ["rit-csci-589"]
       },
       {
         "title": "Evaluation Criteria and Quality Standards",
         "claim": "Professionals should strive to achieve high quality in both processes and products, and maintain high standards of professional competence.",
         "example": "Students apply a rubric that scores their proposal on clarity, methodological rigor, ethical compliance, and alignment with advisor goals.",
         "visualDirection": "Present a scoring matrix with categories: 'Problem Definition', 'Methodology', 'Ethics', 'Communication', and 'Feasibility' with 1-5 scales.",
         "sourceIds": ["acm-code-of-ethics", "acm-research-practice"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students must submit a thesis proposal for approval to the advisor at the end of the semester, ensuring all components are complete and compliant.",
         "example": "Students run a final review against a checklist: problem statement, literature review, reproducible methods, ethical considerations, citations, and advisor deliverables.",
         "visualDirection": "Show a printable checklist template with checkboxes for each requirement, a signature line for advisor approval, and a submission deadline field.",
         "sourceIds": ["rit-csci-589"]
       }
     ]
   }
